package kr.local.roadsafety;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 TextView status; boolean running=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(32,50,32,24);box.setBackgroundColor(Color.rgb(241,247,255));TextView title=new TextView(this);title.setText("도로안심 GPS · APK 시험판");title.setTextSize(24);box.addView(title);status=new TextView(this);status.setText("GPS 중지 · 실제 카메라/사고 경고는 아직 미연동");status.setTextSize(17);box.addView(status);Button start=new Button(this);start.setText("GPS 추적 시작");box.addView(start);start.setOnClickListener(v->start());Button stop=new Button(this);stop.setText("GPS 중지");box.addView(stop);stop.setOnClickListener(v->{stopService(new Intent(this,LocationService.class));status.setText("GPS 중지");});Button vibration=new Button(this);vibration.setText("진동 시험");box.addView(vibration);vibration.setOnClickListener(v->{android.os.Vibrator vib=(android.os.Vibrator)getSystemService(VIBRATOR_SERVICE);if(Build.VERSION.SDK_INT>=26)vib.vibrate(VibrationEffect.createOneShot(250,VibrationEffect.DEFAULT_AMPLITUDE));});TextView note=new TextView(this);note.setText("시험용 네이티브 GPS: 화면을 잠근 상태에서 서비스 알림이 유지되는지 확인하세요. 배터리 최적화·권한 설정에 따라 중단될 수 있습니다. 운전 중 조작 금지.");box.addView(note);setContentView(box);}
 void start(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},12);}if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},11);return;}try{Intent i=new Intent(this,LocationService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("GPS 서비스 시작 요청 · 상단 알림 확인");}catch(Exception e){status.setText("GPS 시작 실패: "+e.getMessage());}}
 @Override public void onRequestPermissionsResult(int code,String[] p,int[] g){super.onRequestPermissionsResult(code,p,g);if(code==11&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)start();}
}
